const notification = document.getElementById("notification");
notification.style.display = "block";
notification.style.background = "#ff9800";

const title = document.getElementById("title");
title.style.color = "#1565c0";
title.style.fontSize = "2rem";

const product = document.getElementById("product-1");
const computed = window.getComputedStyle(product);
console.log(computed.borderRadius);

const notification = document.getElementById("notification");
const computed = window.getComputedStyle(notification);
console.log(computed.padding);

document.documentElement.style.setProperty("--main-color", "#e91e63");
const mainColor = getComputedStyle(document.documentElement).getPropertyValue("--main-color");
console.log(mainColor); // "#e91e63"

// Wersja z wieloma inline styles (mniej zalecana):
const notification = document.getElementById("notification");
notification.style.display = "block";
notification.style.background = "#4caf50";
notification.style.padding = "1rem";
notification.style.borderRadius = "4px";

// Wersja z klasa CSS (lepsza praktyka):
// W pliku CSS: .notification-success { display: block; background: #4caf50; padding: 1rem; border-radius: 4px; }
notification.classList.add("notification-success");

// Uzycie gotowej klasy jest lepsza praktyka, poniewaz ROZDZIELA logike
// (KIEDY pokazac dany styl - decyzja podejmowana w JavaScript) od
// samego wygladu (JAKIE dokladnie wartosci CSS sklada sie na ten styl -
// zdefiniowane w pliku CSS). Ulatwia to zarzadzanie wygladem w jednym
// miejscu (pliku CSS) i unika 'rozmycia' logiki stylu pomiedzy JS i CSS.

const produkt = document.getElementById("product-1");
produkt.style.opacity = "0.5";
produkt.style.cursor = "pointer";

const powiadomienie = document.getElementById("notification");
console.log(powiadomienie.style.display);
powiadomienie.style.display = "none";
console.log(powiadomienie.style.display);

const produkt = document.getElementById("product-2");
const computed = window.getComputedStyle(produkt);
console.log(computed.display);

document.documentElement.style.setProperty("--akcent-color", "#673ab7");
const kolor = getComputedStyle(document.documentElement).getPropertyValue("--akcent-color");
console.log(kolor);

function ustawWidocznosc(elementId, widoczny) {
  document.getElementById(elementId).style.display = widoczny ? "block" : "none";
}

ustawWidocznosc("notification", true);
console.log(document.getElementById("notification").style.display);
ustawWidocznosc("notification", false);
console.log(document.getElementById("notification").style.display);

function cssNaCamelCase(nazwa) {
  return nazwa.replace(/-([a-z])/g, (_, litera) => litera.toUpperCase());
}

console.log(cssNaCamelCase("background-color"));
console.log(cssNaCamelCase("font-size"));

function camelCaseNaCss(nazwa) {
  return nazwa.replace(/[A-Z]/g, (litera) => "-" + litera.toLowerCase());
}

console.log(camelCaseNaCss("backgroundColor"));
console.log(camelCaseNaCss("fontSize"));

const produkt = document.getElementById("product-1");
produkt.style.border = "1px solid #ccc";
produkt.style.padding = "1rem";
produkt.style.borderRadius = "4px";
console.log(produkt.style.border, produkt.style.padding, produkt.style.borderRadius);

// element.style pokazuje WYLACZNIE style ustawione bezposrednio (inline)
// przez JavaScript lub atrybut style="..." w HTML. Jesli kolor tla
// pochodzi z ZEWNETRZNEGO pliku CSS (regula .card { background-color: ... }),
// element.style.backgroundColor zwroci PUSTY string, mimo ze kolor JEST
// faktycznie zastosowany i widoczny na stronie - trzeba uzyc
// getComputedStyle, zeby zobaczyc FAKTYCZNIE zastosowany styl,
// niezaleznie od jego zrodla.

const produkt = document.getElementById("product-1");
const computed = window.getComputedStyle(produkt);
console.log(computed.borderRadius, computed.padding);

function zastosujMotyw(kolorGlowny) {
  document.documentElement.style.setProperty("--main-color", kolorGlowny);
}

zastosujMotyw("#e91e63");
console.log(getComputedStyle(document.documentElement).getPropertyValue("--main-color"));

const powiadomienie = document.getElementById("notification");
Object.assign(powiadomienie.style, { display: "block", padding: "1rem", background: "#4caf50" });
console.log(powiadomienie.style.display, powiadomienie.style.padding, powiadomienie.style.background);

// Zamiast wielu linii ustawiajacych pojedyncze wlasciwosci:
// element.style.display = "block";
// element.style.background = "#4caf50";
// element.style.padding = "1rem";
//
// Lepsza praktyka to zdefiniowanie gotowej klasy w pliku CSS:
// .powiadomienie-sukces { display: block; background: #4caf50; padding: 1rem; }
// i dodanie jej jedna linia: element.classList.add("powiadomienie-sukces");
// Rozdziela to logike (KIEDY pokazac styl, JS) od wygladu (JAKIE
// wartosci, CSS), co ulatwia utrzymanie kodu.

const produkt = document.getElementById("product-2");
const computed = window.getComputedStyle(produkt);
console.log(computed.display !== "");

function pobierzZmiennaCss(nazwa) {
  return getComputedStyle(document.documentElement).getPropertyValue(nazwa);
}

document.documentElement.style.setProperty("--test-var", "10px");
console.log(pobierzZmiennaCss("--test-var"));

const tytul = document.getElementById("title");
tytul.style.color = "#1565c0";
tytul.style.removeProperty("color");
console.log(tytul.style.color === "");

function zmienKolorGlowny(nowyKolor) {
  document.documentElement.style.setProperty("--main-color", nowyKolor);
  return getComputedStyle(document.documentElement).getPropertyValue("--main-color");
}

console.log(zmienKolorGlowny("#00bcd4"));

const produkt = document.getElementById("product-1");
produkt.style.border = "2px solid red";
console.log(produkt.style.border.length > 0);

const styl = {};
Object.assign(styl, { color: "red", fontSize: "16px" });
console.log(styl);

function kluczeCamelCase(obiektStylow) {
  return Object.keys(obiektStylow).filter((k) => /[A-Z]/.test(k));
}

console.log(kluczeCamelCase({ color: "red", backgroundColor: "blue", opacity: "0.5" }));

document.body.style.margin = "0";
document.body.style.fontFamily = "sans-serif";
console.log(document.body.style.margin, document.body.style.fontFamily);

